import apiClient from './client'
import type { Page, PageParams } from './page'

export interface NodeRead {
  id: number
  node_id: string
  name: string
  host?: string | null
  description?: string | null
  platform: string
  group?: string | null
  labels?: Record<string, unknown> | null
  status: string
  last_seen?: string | null
  is_local: boolean
  is_deleted: boolean
  created_at: string
  updated_at: string
}

export interface NodeCreate {
  name: string
  host?: string
  description?: string
  platform?: string
  group?: string
  labels?: Record<string, unknown>
}

export interface NodeUpdate {
  name?: string
  host?: string
  description?: string
  platform?: string
  group?: string
  labels?: Record<string, unknown>
}

export interface NodeInstallInfo {
  linux_command: string
  windows_command: string
  install_key_expires_at: string
}

export interface BulkNodeResultItem {
  name?: string | null
  node_id?: string | null
  status: string
  error?: string | null
}

export interface BulkNodeCreateResponse {
  task_id: number
  total_count: number
  success_count: number
  failure_count: number
  results: BulkNodeResultItem[]
  install_script_url: string
}

export interface BulkNodeItem {
  name: string
  host: string
  platform: string
  group?: string
  labels?: Record<string, unknown>
  description?: string
}

export interface BulkNodeCreateRequest {
  nodes: BulkNodeItem[]
}

export interface NodeListParams extends PageParams {
  group?: string
  label_key?: string
  label_value?: string
}

export async function getNodes(params?: NodeListParams): Promise<Page<NodeRead>> {
  const response = await apiClient.get<Page<NodeRead>>('/v1/nodes', { params })
  return response.data
}

export async function createNode(data: NodeCreate): Promise<NodeRead> {
  const response = await apiClient.post<NodeRead>('/v1/nodes', data)
  return response.data
}

export async function getNode(nodeId: number): Promise<NodeRead> {
  const response = await apiClient.get<NodeRead>(`/v1/nodes/${nodeId}`)
  return response.data
}

export async function updateNode(nodeId: number, data: NodeUpdate): Promise<NodeRead> {
  const response = await apiClient.put<NodeRead>(`/v1/nodes/${nodeId}`, data)
  return response.data
}

export async function deleteNode(nodeId: number): Promise<void> {
  await apiClient.delete(`/v1/nodes/${nodeId}`)
}

export async function resetNodeToken(nodeId: number): Promise<NodeRead> {
  const response = await apiClient.post<NodeRead>(`/v1/nodes/${nodeId}/reset-token`)
  return response.data
}

export async function getInstallCommand(nodeId: number): Promise<NodeInstallInfo> {
  const response = await apiClient.get<NodeInstallInfo>(`/v1/nodes/${nodeId}/install`)
  return response.data
}

export async function bulkCreateNodes(data: BulkNodeCreateRequest): Promise<BulkNodeCreateResponse> {
  const response = await apiClient.post<BulkNodeCreateResponse>('/v1/nodes/batch', data)
  return response.data
}

export async function bulkCreateNodesFromCsv(file: File): Promise<BulkNodeCreateResponse> {
  const formData = new FormData()
  formData.append('file', file)
  const response = await apiClient.post<BulkNodeCreateResponse>('/v1/nodes/batch/csv', formData, {
    headers: {
      'Content-Type': 'multipart/form-data',
    },
  })
  return response.data
}

export async function getBulkTask(taskId: number): Promise<BulkNodeCreateResponse> {
  const response = await apiClient.get<BulkNodeCreateResponse>(`/v1/nodes/batch/${taskId}`)
  return response.data
}

export function getBulkInstallScriptUrl(taskId: number): string {
  return `/api/v1/nodes/batch/${taskId}/install-script`
}
